CREATE TABLE public.ocean_chest_control (id boolean PRIMARY KEY DEFAULT true CHECK(id), config jsonb NOT NULL DEFAULT '{"enabled":true,"maxActive":24,"minInterval":30,"maxInterval":120,"lifetime":1800,"minDistance":180,"collectRadius":100,"cooldown":10,"dailyClaims":100,"dailyTon":0,"monthlyTon":0,"fallback":null,"regions":[{"id":"open-sea","minX":-4800,"maxX":7200,"minY":-4800,"maxY":7200,"rarity":"common"}],"equipmentMaterials":{}}', funded numeric(20,9) NOT NULL DEFAULT 0 CHECK(funded>=0), reserved numeric(20,9) NOT NULL DEFAULT 0 CHECK(reserved>=0), earned numeric(20,9) NOT NULL DEFAULT 0 CHECK(earned>=0), paid numeric(20,9) NOT NULL DEFAULT 0 CHECK(paid>=0), next_spawn timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(funded>=reserved+earned+paid));
GRANT ALL ON public.ocean_chest_control TO service_role;
ALTER TABLE public.ocean_chest_control ENABLE ROW LEVEL SECURITY;
CREATE POLICY ocean_control_service ON public.ocean_chest_control TO service_role USING(true) WITH CHECK(true);
CREATE TABLE public.ocean_chests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), region text NOT NULL, rarity text NOT NULL, x double precision NOT NULL, y double precision NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'available' CHECK(status IN ('available','reserved','collected','expired')), reward_table jsonb NOT NULL, reservation numeric(20,9) NOT NULL DEFAULT 0 CHECK(reservation>=0), budget_day date NOT NULL DEFAULT (now() AT TIME ZONE 'UTC')::date, winner uuid, collected_at timestamptz, reward jsonb, CHECK((status='collected')=(winner IS NOT NULL)), CHECK(x NOT IN ('NaN'::float8,'Infinity'::float8,'-Infinity'::float8) AND y NOT IN ('NaN'::float8,'Infinity'::float8,'-Infinity'::float8)));
GRANT ALL ON public.ocean_chests TO service_role;
ALTER TABLE public.ocean_chests ENABLE ROW LEVEL SECURITY;
CREATE POLICY ocean_chests_service ON public.ocean_chests TO service_role USING(true) WITH CHECK(true);
CREATE INDEX ocean_chests_active ON public.ocean_chests(expires_at) WHERE status='available';
CREATE TABLE public.ocean_chest_claims (chest_id uuid PRIMARY KEY REFERENCES public.ocean_chests(id), user_id uuid NOT NULL, reward jsonb NOT NULL, ton numeric(20,9) NOT NULL DEFAULT 0 CHECK(ton>=0), payment_status text NOT NULL DEFAULT 'not_applicable' CHECK(payment_status IN ('not_applicable','pending_review','paid','failed')), transaction_hash text UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), paid_at timestamptz);
GRANT ALL ON public.ocean_chest_claims TO service_role;
ALTER TABLE public.ocean_chest_claims ENABLE ROW LEVEL SECURITY;
CREATE POLICY ocean_claims_service ON public.ocean_chest_claims TO service_role USING(true) WITH CHECK(true);
CREATE INDEX ocean_claims_user ON public.ocean_chest_claims(user_id,created_at DESC);
CREATE TABLE public.ocean_chest_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, kind text NOT NULL, reference text, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.ocean_chest_audit TO service_role;
ALTER TABLE public.ocean_chest_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY ocean_audit_service ON public.ocean_chest_audit TO service_role USING(true) WITH CHECK(true);
CREATE TABLE public.ocean_equipment_uses (equipment_id uuid PRIMARY KEY, user_id uuid NOT NULL, materials jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.ocean_equipment_uses TO service_role;
ALTER TABLE public.ocean_equipment_uses ENABLE ROW LEVEL SECURITY;
CREATE POLICY ocean_equipment_service ON public.ocean_equipment_uses TO service_role USING(true) WITH CHECK(true);
CREATE OR REPLACE FUNCTION public.ocean_default_odds() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT '[{"kind":"material","weight":40},{"kind":"equipment","weight":25},{"kind":"mascot","weight":12},{"kind":"ton","amount":0.001,"weight":12},{"kind":"ton","amount":0.01,"weight":6},{"kind":"ton","amount":0.05,"weight":3},{"kind":"ton","amount":0.1,"weight":1.8},{"kind":"ton","amount":0.5,"weight":0.2}]'::jsonb $$;
CREATE OR REPLACE FUNCTION public.ocean_random() RETURNS double precision LANGUAGE plpgsql VOLATILE SET search_path=public AS $$ DECLARE b bytea:=extensions.gen_random_bytes(6); n numeric:=0; i integer; BEGIN FOR i IN 0..5 LOOP n:=n*256+get_byte(b,i); END LOOP; RETURN (n/281474976710656)::double precision; END $$;
CREATE OR REPLACE FUNCTION public.ocean_validate_odds(p_table jsonb,p_no_ton boolean DEFAULT false) RETURNS numeric LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE e jsonb; total numeric:=0; maximum numeric:=0; BEGIN IF jsonb_typeof(p_table) IS DISTINCT FROM 'array' OR jsonb_array_length(p_table) NOT BETWEEN 1 AND 32 THEN RAISE EXCEPTION 'OCEAN_INVALID_ODDS'; END IF; FOR e IN SELECT value FROM jsonb_array_elements(p_table) LOOP IF e->>'kind' NOT IN ('material','equipment','mascot','ton') OR e->>'kind' IS NULL OR jsonb_typeof(e->'weight') IS DISTINCT FROM 'number' OR (e->>'weight')::numeric<=0 THEN RAISE EXCEPTION 'OCEAN_INVALID_ODDS'; END IF; total:=total+(e->>'weight')::numeric; IF e->>'kind'='ton' THEN IF p_no_ton OR jsonb_typeof(e->'amount') IS DISTINCT FROM 'number' OR (e->>'amount')::numeric NOT IN (.001,.01,.05,.1,.5) THEN RAISE EXCEPTION 'OCEAN_INVALID_ODDS'; END IF; maximum:=greatest(maximum,(e->>'amount')::numeric); END IF; END LOOP; IF total<>100 THEN RAISE EXCEPTION 'OCEAN_ODDS_MUST_TOTAL_100'; END IF; RETURN maximum; END $$;
CREATE OR REPLACE FUNCTION public.ocean_chest_tick(p_user uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c ocean_chest_control; r jsonb; odds jsonb; max_ton numeric; release numeric; active integer; spawn_x float8; spawn_y float8; attempt integer; day_used numeric; month_used numeric; epoch timestamptz; state text:='active'; BEGIN
IF coalesce((SELECT value='true'::jsonb FROM game_settings WHERE key='game_reset_in_progress'),false) THEN RETURN 'paused'; END IF;
IF NOT EXISTS(SELECT 1 FROM game_players WHERE id=p_user AND NOT coalesce(banned,false)) THEN RAISE EXCEPTION 'PLAYER_NOT_FOUND'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended('ocean-chest-world',0)); INSERT INTO ocean_chest_control(id) VALUES(true) ON CONFLICT DO NOTHING; SELECT * INTO c FROM ocean_chest_control WHERE id=true FOR UPDATE;
epoch:=coalesce((SELECT (value #>> '{}')::timestamptz FROM game_settings WHERE key='game_reset_epoch'),'-infinity'::timestamptz);
SELECT coalesce(sum(reservation),0) INTO release FROM ocean_chests WHERE status='available' AND (expires_at<=now() OR created_at<epoch); UPDATE ocean_chests SET status='expired' WHERE status='available' AND (expires_at<=now() OR created_at<epoch); IF release>0 THEN UPDATE ocean_chest_control SET reserved=reserved-release WHERE id=true; c.reserved:=c.reserved-release; END IF;
IF NOT (c.config->>'enabled')::boolean OR (c.config->>'eventEndsAt' IS NOT NULL AND (c.config->>'eventEndsAt')::timestamptz<=now()) OR (c.config->>'eventStartsAt' IS NOT NULL AND (c.config->>'eventStartsAt')::timestamptz>now()) THEN RETURN 'paused'; END IF;
SELECT count(*) INTO active FROM ocean_chests WHERE status='available'; r:=c.config->'regions'->floor(ocean_random()*jsonb_array_length(c.config->'regions'))::integer; odds:=coalesce(r->'odds',c.config->'odds',ocean_default_odds()); max_ton:=ocean_validate_odds(odds);
SELECT coalesce(sum(CASE WHEN status='available' THEN reservation WHEN status='collected' THEN (reward->>'amount')::numeric ELSE 0 END),0) INTO day_used FROM ocean_chests WHERE budget_day=(now() AT TIME ZONE 'UTC')::date AND (status='available' OR (status='collected' AND reward->>'kind'='ton'));
SELECT coalesce(sum(CASE WHEN status='available' THEN reservation WHEN status='collected' THEN (reward->>'amount')::numeric ELSE 0 END),0) INTO month_used FROM ocean_chests WHERE budget_day>=date_trunc('month',now() AT TIME ZONE 'UTC')::date AND (status='available' OR (status='collected' AND reward->>'kind'='ton'));
IF max_ton>0 AND (c.funded-c.reserved-c.earned-c.paid<max_ton OR day_used+max_ton>(c.config->>'dailyTon')::numeric OR month_used+max_ton>(c.config->>'monthlyTon')::numeric) THEN IF c.config->'fallback' IS NULL OR c.config->'fallback'='null'::jsonb THEN RETURN 'budget_unavailable'; END IF; odds:=c.config->'fallback'; max_ton:=ocean_validate_odds(odds,true); state:='alternative'; END IF;
IF EXISTS(SELECT 1 FROM jsonb_array_elements(odds) e WHERE (e->>'kind'='equipment' AND NOT EXISTS(SELECT 1 FROM equipment_templates WHERE is_active AND NOT is_nft AND NOT veteran_line AND NOT founder_line AND rarity IN ('common','uncommon','rare','epic','legendary','mythic'))) OR (e->>'kind'='mascot' AND NOT EXISTS(SELECT 1 FROM pets WHERE is_enabled AND NOT is_nft_exclusive AND NOT is_pass_exclusive AND NOT is_season_exclusive AND NOT veteran_line AND rarity IN ('common','rare','epic','legendary','mythic'))) OR (e->>'kind'='material' AND (SELECT count(*) FROM realm_materials WHERE id IN ('magic_wood','nails','rope'))<>3)) THEN RETURN 'catalog_unavailable'; END IF;
IF active>=(c.config->>'maxActive')::integer OR c.next_spawn>now() THEN RETURN state; END IF;
FOR attempt IN 1..48 LOOP spawn_x:=(r->>'minX')::float8+ocean_random()*((r->>'maxX')::float8-(r->>'minX')::float8); spawn_y:=(r->>'minY')::float8+ocean_random()*((r->>'maxY')::float8-(r->>'minY')::float8);
IF NOT naval_ocean_land(spawn_x,spawn_y) AND NOT EXISTS(SELECT 1 FROM ocean_chests o WHERE status='available' AND sqrt(power(o.x-spawn_x,2)+power(o.y-spawn_y,2))<(c.config->>'minDistance')::float8) THEN INSERT INTO ocean_chests(region,rarity,x,y,expires_at,reward_table,reservation) VALUES(r->>'id',r->>'rarity',spawn_x,spawn_y,now()+make_interval(secs=>(c.config->>'lifetime')::integer),odds,max_ton); UPDATE ocean_chest_control SET reserved=reserved+max_ton,next_spawn=now()+make_interval(secs=>((c.config->>'minInterval')::float8+ocean_random()*((c.config->>'maxInterval')::float8-(c.config->>'minInterval')::float8))::integer) WHERE id=true; RETURN state; END IF; END LOOP; RETURN 'no_water'; END $$;
CREATE OR REPLACE FUNCTION public.ocean_chest_view(p_user uuid,p_emission text DEFAULT 'active') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s naval_ships; c ocean_chest_control; BEGIN SELECT * INTO s FROM naval_ships WHERE user_id=p_user; SELECT * INTO c FROM ocean_chest_control WHERE id=true;
RETURN jsonb_build_object('emission',p_emission,'collectRadius',coalesce((c.config->>'collectRadius')::integer,100),'odds',coalesce(c.config->'odds',ocean_default_odds()),'alternativeOdds',c.config->'fallback','chests',coalesce((SELECT jsonb_agg(jsonb_build_object('id',o.id,'region',o.region,'rarity',o.rarity,'x',o.x,'y',o.y,'expiresAt',o.expires_at,'odds',o.reward_table)) FROM ocean_chests o WHERE o.status='available' AND o.expires_at>now() AND o.created_at>=coalesce((SELECT (value #>> '{}')::timestamptz FROM game_settings WHERE key='game_reset_epoch'),'-infinity'::timestamptz) AND sqrt(power(o.x-s.x,2)+power(o.y-s.y,2))<1000),'[]'::jsonb),'history',coalesce((SELECT jsonb_agg(t) FROM (SELECT chest_id,reward,payment_status,created_at FROM ocean_chest_claims WHERE user_id=p_user ORDER BY created_at DESC LIMIT 20)t),'[]'::jsonb),'equipmentQuotes',coalesce((SELECT jsonb_agg(jsonb_build_object('id',e.id,'name',t.name,'materials',c.config->'equipmentMaterials'->t.rarity)) FROM player_equipment e JOIN equipment_templates t ON t.id=e.template_id WHERE e.user_id=p_user AND e.source='ocean_chest' AND e.hero_id IS NULL AND NOT e.locked AND NOT e.market_locked AND NOT EXISTS(SELECT 1 FROM ocean_equipment_uses u WHERE u.equipment_id=e.id) AND c.config->'equipmentMaterials' ? t.rarity),'[]'::jsonb)); END $$;
CREATE OR REPLACE FUNCTION public.ocean_chest_claim(p_user uuid,p_chest uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s naval_ships; o ocean_chests; c ocean_chest_control; e jsonb; prize jsonb; roll float8:=ocean_random()*100; cumulative numeric:=0; template equipment_templates; pet pets; item uuid; material text; before_amount numeric; prize_amount numeric; old ocean_chest_claims; error_code text; BEGIN
PERFORM pg_advisory_xact_lock(hashtextextended('naval-world',0)); PERFORM pg_advisory_xact_lock(hashtextextended('ocean-chest-world',0)); SELECT * INTO c FROM ocean_chest_control WHERE id=true FOR UPDATE; SELECT * INTO s FROM naval_ships WHERE user_id=p_user FOR UPDATE;
IF NOT EXISTS(SELECT 1 FROM game_players WHERE id=p_user AND NOT coalesce(banned,false)) THEN RAISE EXCEPTION 'PLAYER_NOT_FOUND'; END IF; IF coalesce((SELECT value='true'::jsonb FROM game_settings WHERE key='game_reset_in_progress'),false) THEN RETURN jsonb_build_object('error','GAME_RESET'); END IF;
SELECT * INTO old FROM ocean_chest_claims WHERE chest_id=p_chest; IF old.chest_id IS NOT NULL AND old.user_id=p_user THEN RETURN jsonb_build_object('reward',old.reward,'replayed',true); END IF;
SELECT * INTO o FROM ocean_chests WHERE id=p_chest FOR UPDATE;
IF o.id IS NULL OR o.status<>'available' OR o.expires_at<=now() THEN error_code:='OCEAN_CHEST_UNAVAILABLE'; ELSIF o.created_at<coalesce((SELECT (value #>> '{}')::timestamptz FROM game_settings WHERE key='game_reset_epoch'),'-infinity'::timestamptz) THEN error_code:='GAME_RESET'; ELSIF NOT coalesce((c.config->>'enabled')::boolean,false) OR (c.config->>'eventEndsAt' IS NOT NULL AND (c.config->>'eventEndsAt')::timestamptz<=now()) OR (c.config->>'eventStartsAt' IS NOT NULL AND (c.config->>'eventStartsAt')::timestamptz>now()) THEN error_code:='OCEAN_PAUSED'; ELSIF s.user_id IS NULL OR s.seen_at<now()-interval '8 seconds' OR s.hp<=0 OR s.battle_id IS NOT NULL OR sqrt(power(s.x-o.x,2)+power(s.y-o.y,2))>(c.config->>'collectRadius')::float8 THEN error_code:='OCEAN_OUT_OF_RANGE'; ELSIF EXISTS(SELECT 1 FROM ocean_chest_claims WHERE user_id=p_user AND created_at>now()-make_interval(secs=>(c.config->>'cooldown')::integer)) OR (SELECT count(*) FROM ocean_chest_claims WHERE user_id=p_user AND created_at>=date_trunc('day',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC')>=(c.config->>'dailyClaims')::integer THEN error_code:='OCEAN_CLAIM_LIMIT'; END IF;
IF error_code IS NOT NULL THEN INSERT INTO ocean_chest_audit(user_id,kind,reference,details) VALUES(p_user,'claim_rejected',p_chest::text,jsonb_build_object('code',error_code)); RETURN jsonb_build_object('error',error_code); END IF;
PERFORM ocean_validate_odds(o.reward_table); FOR e IN SELECT value FROM jsonb_array_elements(o.reward_table) LOOP cumulative:=cumulative+(e->>'weight')::numeric; IF roll<cumulative THEN prize:=e-'weight'; EXIT; END IF; END LOOP;
IF prize->>'kind'='material' THEN SELECT id INTO material FROM realm_materials WHERE id IN ('magic_wood','nails','rope') ORDER BY ocean_random() LIMIT 1; IF material IS NULL THEN RETURN jsonb_build_object('error','OCEAN_CATALOG_UNAVAILABLE'); END IF; prize_amount:=1+floor(ocean_random()*3); INSERT INTO realm_material_balances(user_id,material_id,amount) VALUES(p_user,material,0) ON CONFLICT DO NOTHING; SELECT b.amount INTO before_amount FROM realm_material_balances b WHERE user_id=p_user AND material_id=material FOR UPDATE; UPDATE realm_material_balances SET amount=realm_material_balances.amount+prize_amount,updated_at=now() WHERE user_id=p_user AND material_id=material; INSERT INTO realm_material_ledger(user_id,material_id,amount,balance_before,balance_after,reason,source_id) VALUES(p_user,material,prize_amount,before_amount,before_amount+prize_amount,'ocean_chest',o.id::text); prize:=prize||jsonb_build_object('material',material,'amount',prize_amount);
ELSIF prize->>'kind'='equipment' THEN SELECT * INTO template FROM equipment_templates WHERE is_active AND NOT is_nft AND NOT veteran_line AND NOT founder_line AND rarity IN ('common','uncommon','rare','epic','legendary','mythic') ORDER BY ocean_random() LIMIT 1; IF template.id IS NULL THEN RETURN jsonb_build_object('error','OCEAN_CATALOG_UNAVAILABLE'); END IF; INSERT INTO player_equipment(user_id,template_id,source,source_ref) VALUES(p_user,template.id,'ocean_chest',o.id) RETURNING id INTO item; prize:=prize||jsonb_build_object('itemId',item,'name',template.name,'rarity',template.rarity,'image',template.image_url);
ELSIF prize->>'kind'='mascot' THEN SELECT * INTO pet FROM pets WHERE is_enabled AND NOT is_nft_exclusive AND NOT is_pass_exclusive AND NOT is_season_exclusive AND NOT veteran_line AND rarity IN ('common','rare','epic','legendary','mythic') ORDER BY ocean_random() LIMIT 1; IF pet.id IS NULL THEN RETURN jsonb_build_object('error','OCEAN_CATALOG_UNAVAILABLE'); END IF; INSERT INTO player_pets(user_id,pet_id,rarity) VALUES(p_user,pet.id,pet.rarity) RETURNING id INTO item; prize:=prize||jsonb_build_object('itemId',item,'name',pet.name,'rarity',pet.rarity,'image',pet.image_baby_url);
ELSE prize_amount:=(prize->>'amount')::numeric; IF prize_amount>o.reservation OR c.reserved<o.reservation THEN RAISE EXCEPTION 'OCEAN_BUDGET_INVARIANT'; END IF; prize:=prize||jsonb_build_object('paymentStatus','pending_review'); END IF;
UPDATE ocean_chest_control SET reserved=reserved-o.reservation,earned=earned+CASE WHEN prize->>'kind'='ton' THEN (prize->>'amount')::numeric ELSE 0 END WHERE id=true; UPDATE ocean_chests SET status='collected',winner=p_user,collected_at=now(),reward=prize WHERE id=o.id; INSERT INTO ocean_chest_claims(chest_id,user_id,reward,ton,payment_status) VALUES(o.id,p_user,prize,CASE WHEN prize->>'kind'='ton' THEN (prize->>'amount')::numeric ELSE 0 END,CASE WHEN prize->>'kind'='ton' THEN 'pending_review' ELSE 'not_applicable' END); INSERT INTO ocean_chest_audit(user_id,kind,reference,details) VALUES(p_user,'collected',o.id::text,prize); RETURN jsonb_build_object('reward',prize,'replayed',false); END $$;
CREATE OR REPLACE FUNCTION public.ocean_equipment_use(p_user uuid,p_equipment uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e player_equipment; t equipment_templates; materials jsonb; m record; before_amount numeric; BEGIN
PERFORM pg_advisory_xact_lock(hashtextextended('naval-world',0)); IF coalesce((SELECT value='true'::jsonb FROM game_settings WHERE key='game_reset_in_progress'),false) OR NOT EXISTS(SELECT 1 FROM game_players WHERE id=p_user AND NOT coalesce(banned,false)) THEN RAISE EXCEPTION 'REALM_LOCKED'; END IF; IF EXISTS(SELECT 1 FROM ocean_equipment_uses WHERE equipment_id=p_equipment AND user_id=p_user) THEN RETURN jsonb_build_object('replayed',true); END IF; SELECT * INTO e FROM player_equipment WHERE id=p_equipment AND user_id=p_user FOR UPDATE; IF e.id IS NULL OR e.source<>'ocean_chest' OR e.hero_id IS NOT NULL OR e.locked OR e.market_locked THEN RAISE EXCEPTION 'OCEAN_EQUIPMENT_LOCKED'; END IF; SELECT * INTO t FROM equipment_templates WHERE id=e.template_id; SELECT config->'equipmentMaterials'->t.rarity INTO materials FROM ocean_chest_control WHERE id=true; IF materials IS NULL OR materials='{}'::jsonb THEN RAISE EXCEPTION 'OCEAN_EQUIPMENT_QUOTE_REQUIRED'; END IF;
FOR m IN SELECT key,value::text::numeric AS amount FROM jsonb_each(materials) ORDER BY key LOOP INSERT INTO realm_material_balances(user_id,material_id,amount) VALUES(p_user,m.key,0) ON CONFLICT DO NOTHING; SELECT amount INTO before_amount FROM realm_material_balances WHERE user_id=p_user AND material_id=m.key FOR UPDATE; UPDATE realm_material_balances SET amount=amount+m.amount,updated_at=now() WHERE user_id=p_user AND material_id=m.key; INSERT INTO realm_material_ledger(user_id,material_id,amount,balance_before,balance_after,reason,source_id) VALUES(p_user,m.key,m.amount,before_amount,before_amount+m.amount,'ocean_equipment',p_equipment::text); END LOOP; INSERT INTO ocean_equipment_uses(equipment_id,user_id,materials) VALUES(e.id,p_user,materials); DELETE FROM player_equipment WHERE id=e.id AND user_id=p_user; RETURN jsonb_build_object('materials',materials); END $$;
CREATE OR REPLACE FUNCTION public.ocean_chest_admin(p_admin bigint,p_patch jsonb DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cfg jsonb; r jsonb; e jsonb; m record; k text; BEGIN IF p_admin IS DISTINCT FROM 8490010993 THEN RAISE EXCEPTION 'UNAUTHORIZED'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('ocean-chest-world',0)); INSERT INTO ocean_chest_control(id) VALUES(true) ON CONFLICT DO NOTHING; SELECT config INTO cfg FROM ocean_chest_control WHERE id=true FOR UPDATE;
IF p_patch IS NOT NULL THEN IF jsonb_typeof(p_patch)<>'object' THEN RAISE EXCEPTION 'OCEAN_INVALID_CONFIG'; END IF; FOR k IN SELECT jsonb_object_keys(p_patch) LOOP IF k NOT IN ('enabled','maxActive','minInterval','maxInterval','lifetime','minDistance','collectRadius','cooldown','dailyClaims','dailyTon','monthlyTon','fallback','odds','regions','equipmentMaterials','eventStartsAt','eventEndsAt') THEN RAISE EXCEPTION 'OCEAN_INVALID_CONFIG'; END IF; END LOOP; cfg:=cfg||p_patch; IF jsonb_typeof(cfg->'enabled') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'OCEAN_INVALID_CONFIG'; END IF;
FOREACH k IN ARRAY ARRAY['maxActive','minInterval','maxInterval','lifetime','minDistance','collectRadius','cooldown','dailyClaims','dailyTon','monthlyTon'] LOOP IF jsonb_typeof(cfg->k) IS DISTINCT FROM 'number' OR (cfg->>k)::numeric<0 THEN RAISE EXCEPTION 'OCEAN_INVALID_CONFIG'; END IF; END LOOP;
IF (cfg->>'maxActive')::numeric NOT BETWEEN 1 AND 200 OR (cfg->>'minInterval')::numeric<5 OR (cfg->>'maxInterval')::numeric<(cfg->>'minInterval')::numeric OR (cfg->>'maxInterval')::numeric>86400 OR (cfg->>'lifetime')::numeric NOT BETWEEN 60 AND 86400 OR (cfg->>'minDistance')::numeric<80 OR (cfg->>'collectRadius')::numeric NOT BETWEEN 30 AND 120 OR (cfg->>'cooldown')::numeric<2 OR (cfg->>'dailyClaims')::numeric NOT BETWEEN 1 AND 1000 OR (cfg->>'dailyTon')::numeric>(cfg->>'monthlyTon')::numeric THEN RAISE EXCEPTION 'OCEAN_INVALID_CONFIG'; END IF;
PERFORM ocean_validate_odds(coalesce(cfg->'odds',ocean_default_odds())); IF cfg->'fallback'<>'null'::jsonb THEN PERFORM ocean_validate_odds(cfg->'fallback',true); END IF;
IF jsonb_typeof(cfg->'regions') IS DISTINCT FROM 'array' OR jsonb_array_length(cfg->'regions') NOT BETWEEN 1 AND 30 THEN RAISE EXCEPTION 'OCEAN_INVALID_CONFIG'; END IF;
FOR r IN SELECT value FROM jsonb_array_elements(cfg->'regions') LOOP IF coalesce(r->>'id','') !~ '^[a-z0-9-]{1,40}$' OR coalesce(r->>'rarity','') NOT IN ('common','rare','epic','legendary','mythic') THEN RAISE EXCEPTION 'OCEAN_INVALID_REGION'; END IF; FOREACH k IN ARRAY ARRAY['minX','maxX','minY','maxY'] LOOP IF jsonb_typeof(r->k) IS DISTINCT FROM 'number' OR abs((r->>k)::numeric)>10000000 THEN RAISE EXCEPTION 'OCEAN_INVALID_REGION'; END IF; END LOOP; IF (r->>'minX')::numeric>=(r->>'maxX')::numeric OR (r->>'minY')::numeric>=(r->>'maxY')::numeric THEN RAISE EXCEPTION 'OCEAN_INVALID_REGION'; END IF; IF r ? 'odds' THEN PERFORM ocean_validate_odds(r->'odds'); END IF; END LOOP;
IF cfg->>'eventStartsAt' IS NOT NULL THEN PERFORM (cfg->>'eventStartsAt')::timestamptz; END IF; IF cfg->>'eventEndsAt' IS NOT NULL THEN PERFORM (cfg->>'eventEndsAt')::timestamptz; END IF;
IF jsonb_typeof(cfg->'equipmentMaterials') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'OCEAN_INVALID_CONFIG'; END IF; FOR e IN SELECT value FROM jsonb_each(cfg->'equipmentMaterials') LOOP IF jsonb_typeof(e)<>'object' OR e='{}'::jsonb THEN RAISE EXCEPTION 'OCEAN_INVALID_CONFIG'; END IF; FOR m IN SELECT key,value FROM jsonb_each(e) LOOP IF m.key NOT IN ('magic_wood','nails','rope') OR jsonb_typeof(m.value)<>'number' OR m.value::text::numeric NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'OCEAN_INVALID_CONFIG'; END IF; END LOOP; END LOOP;
UPDATE ocean_chest_control SET config=cfg,updated_at=now() WHERE id=true; INSERT INTO ocean_chest_audit(kind,reference,details) VALUES('admin_config',p_admin::text,p_patch); END IF;
RETURN jsonb_build_object('config',cfg,'budget',(SELECT jsonb_build_object('funded',funded,'reserved',reserved,'earned',earned,'paid',paid,'available',funded-reserved-earned-paid) FROM ocean_chest_control WHERE id=true),'pending',(SELECT count(*) FROM ocean_chest_claims WHERE payment_status='pending_review'),'failed',(SELECT count(*) FROM ocean_chest_claims WHERE payment_status='failed'),'active',(SELECT count(*) FROM ocean_chests WHERE status='available' AND expires_at>now())); END $$;
